//! Response lifecycles over an installed store: retention, chaining, background runs, cancel.
use crate::constants::MAX_BACKGROUND_RESPONSES;
use crate::document::Retention;
use crate::persist::StoreLease;
use crate::upstream::Upstream;
use infer_core::{Error, ErrorCode, RequestId, Result};
use infer_spi::{
    ResponseId, ResponseStatus, ResponseStore, ResponseStoreCapabilities, ResponsesExtensions,
    StoredResponse,
};
use std::future::Future;
use std::result::Result as StdResult;
use std::sync::Arc;
use tokio::sync::Semaphore;

/// The response lifecycle service shared by every Responses request of one deployment.
///
/// Cloning is cheap: the store and the background capacity are shared.
#[derive(Clone)]
pub struct Responses {
    extensions: ResponsesExtensions,
    background: Arc<Semaphore>,
}

/// An admitted background generation with the store identity and initial body it starts with.
pub struct BackgroundStart<U: Upstream> {
    pub admitted: U::Admitted,
    pub retention: Retention<U::Document>,
    pub initial: U::Document,
}

impl Responses {
    #[must_use]
    pub fn new(extensions: ResponsesExtensions) -> Self {
        Self {
            extensions,
            background: Arc::new(Semaphore::new(MAX_BACKGROUND_RESPONSES)),
        }
    }

    /// Whether a response store is installed.
    #[must_use]
    pub fn has_store(&self) -> bool {
        self.extensions.store().is_some()
    }

    /// Capabilities of the installed store, or the defaults when none is installed.
    #[must_use]
    pub fn capabilities(&self) -> ResponseStoreCapabilities {
        self.extensions.capabilities().unwrap_or_default()
    }

    fn require_store(&self, purpose: &str) -> Result<&Arc<dyn ResponseStore>> {
        self.extensions.store().ok_or_else(|| {
            Error::unsupported(format!("{purpose} needs an installed response store"))
        })
    }

    /// Load the response a chained request continues.
    ///
    /// # Errors
    /// Returns unsupported without a store, not-found for an unknown id, conflict for a
    /// response that did not complete or end incomplete, and invalid input for a malformed id
    /// or a different model.
    pub async fn prior(
        &self,
        previous: Option<&str>,
        model: &str,
    ) -> Result<Option<StoredResponse>> {
        let Some(previous) = previous else {
            return Ok(None);
        };
        let store = self.require_store("previous_response_id")?;
        let id = ResponseId::new(previous)?;
        let stored = store.get(&id).await?.ok_or_else(|| {
            Error::new(ErrorCode::NotFound, "response not found; see store policy")
        })?;
        if !matches!(
            stored.status,
            ResponseStatus::Completed | ResponseStatus::Incomplete
        ) {
            return Err(Error::new(
                ErrorCode::Conflict,
                "previous response must have completed or ended incomplete",
            ));
        }
        if stored.model != model {
            return Err(Error::invalid(
                "previous_response_id belongs to a different model",
            ));
        }
        Ok(Some(stored))
    }

    /// Read a retained response.
    ///
    /// # Errors
    /// Returns unsupported without a store, invalid input for a malformed id and not-found for
    /// an unknown one.
    pub async fn retrieve(&self, id: &str) -> Result<StoredResponse> {
        let store = self.require_store("response retrieval")?;
        let id = ResponseId::new(id)?;
        store
            .get(&id)
            .await?
            .ok_or_else(|| Error::new(ErrorCode::NotFound, "response not found"))
    }

    /// Mark an active response cancelled, then stop its generation.
    ///
    /// The store transition decides the race with completion; a generation that has already
    /// stopped is not an error.
    ///
    /// # Errors
    /// Returns unsupported without a store, not-found for an unknown id, invalid input for a
    /// terminal response, and the store's conflict when the transition loses a race.
    pub async fn cancel<U: Upstream>(&self, upstream: &U, id: &str) -> Result<StoredResponse> {
        let store = self.require_store("response cancellation")?;
        let id = ResponseId::new(id)?;
        let stored = store
            .get(&id)
            .await?
            .ok_or_else(|| Error::new(ErrorCode::NotFound, "response not found"))?;
        if stored.status.is_terminal() {
            return Err(Error::invalid("a terminal response cannot be cancelled"));
        }
        let updated = store
            .transition(
                &id,
                &[ResponseStatus::Queued, ResponseStatus::InProgress],
                ResponseStatus::Cancelled,
            )
            .await?;
        if let Err(error) = upstream.cancel(updated.request_id).await {
            tracing::debug!(
                target: "infer::agentic",
                error = %error,
                "response was marked cancelled after generation had already stopped"
            );
        }
        Ok(updated)
    }

    /// Reserve capacity, admit a generation, retain it and finish it on its own task.
    ///
    /// Capacity is reserved before `admit` runs, so a full deployment rejects the request
    /// without admitting a generation. The task keeps the reservation until its terminal write
    /// is done; clients poll the store for the result.
    ///
    /// # Errors
    /// Returns unsupported without a store, capacity when every background slot is busy, the
    /// admission error unchanged, or the initial store write error (after cancelling the
    /// generation).
    pub async fn start_background<U: Upstream, E: From<Error>>(
        &self,
        upstream: U,
        admit: impl Future<Output = StdResult<BackgroundStart<U>, E>>,
    ) -> StdResult<U::Document, E> {
        self.require_store("background")?;
        let permit = Arc::clone(&self.background)
            .try_acquire_owned()
            .map_err(|_| {
                Error::new(
                    ErrorCode::Capacity,
                    "background response capacity is exhausted",
                )
            })?;
        let BackgroundStart {
            admitted,
            retention,
            initial,
        } = admit.await?;
        let lease = self.retain(&upstream, retention, &initial).await?;
        tokio::spawn(async move {
            let _permit = permit;
            finish_background(&upstream, admitted, lease).await;
        });
        Ok(initial)
    }

    /// Write the initial in-progress snapshot of an admitted response and arm its cleanup.
    ///
    /// A store failure cancels the admitted generation, so nothing runs unrecorded.
    ///
    /// # Errors
    /// Returns unsupported without a store, or the store's capacity or backend error.
    pub async fn retain<U: Upstream>(
        &self,
        upstream: &U,
        retention: Retention<U::Document>,
        initial: &U::Document,
    ) -> Result<StoreLease<U::Document>> {
        let store = self.require_store("store")?;
        let request = retention.request;
        let mut lease = StoreLease::new(Arc::clone(store), retention);
        if let Err(error) = lease.start(initial).await {
            cancel_after_store_failure(upstream, request).await;
            return Err(error);
        }
        Ok(lease)
    }

    /// Run an admitted generation to completion and record its terminal state.
    ///
    /// # Errors
    /// Returns the generation error (after recording the failure) or the terminal store write
    /// error.
    pub async fn complete<U: Upstream>(
        &self,
        upstream: &U,
        admitted: U::Admitted,
        lease: Option<StoreLease<U::Document>>,
    ) -> Result<U::Document> {
        let mut lease = lease;
        let value = match upstream.complete(admitted).await {
            Ok(value) => value,
            Err(error) => {
                if let Some(lease) = &mut lease
                    && let Err(store_error) = lease.fail(&error).await
                {
                    tracing::error!(
                        target: "infer::agentic",
                        error = %store_error,
                        "failed to retain a failed response"
                    );
                }
                return Err(error);
            }
        };
        if let Some(lease) = &mut lease {
            lease.finish(&value).await?;
        }
        Ok(value)
    }
}

/// Record a background generation's terminal state; no client waits, so store errors are logged.
async fn finish_background<U: Upstream>(
    upstream: &U,
    admitted: U::Admitted,
    mut lease: StoreLease<U::Document>,
) {
    match upstream.complete(admitted).await {
        Ok(value) => {
            if let Err(error) = lease.finish(&value).await {
                tracing::error!(
                    target: "infer::agentic",
                    error = %error,
                    "failed to retain a completed background response"
                );
            }
        }
        Err(error) => {
            if let Err(store_error) = lease.fail(&error).await {
                tracing::error!(
                    target: "infer::agentic",
                    error = %store_error,
                    "failed to retain a failed background response"
                );
            }
        }
    }
}

/// Best effort: the store failure is what the caller reports, so a cancel failure is only logged.
async fn cancel_after_store_failure<U: Upstream>(upstream: &U, request: RequestId) {
    if let Err(error) = upstream.cancel(request).await {
        tracing::warn!(target: "infer::agentic", %error, "generation cancel after a store failure failed");
    }
}

//! Persistence of one response through an installed [`ResponseStore`].
use crate::document::{FailedDocument, ResponseDocument, Retention};
use infer_core::{Error, ErrorCode, RequestId, Result};
use infer_spi::{
    RESPONSES_PAYLOAD_VERSION, ResponseId, ResponseStatus, ResponseStore, StoredResponse,
    WriteCondition,
};
use std::sync::Arc;
use tokio::runtime::Handle;

/// One response's retained state handles. Cloneable so a background task or the disconnect
/// cleanup can finish the store write after the protocol response has returned.
struct StoreSink<D> {
    store: Arc<dyn ResponseStore>,
    id: ResponseId,
    request: RequestId,
    model: String,
    created: u64,
    previous: Option<ResponseId>,
    request_input: Vec<u8>,
    failed: FailedDocument<D>,
}

impl<D> Clone for StoreSink<D> {
    fn clone(&self) -> Self {
        Self {
            store: Arc::clone(&self.store),
            id: self.id.clone(),
            request: self.request,
            model: self.model.clone(),
            created: self.created,
            previous: self.previous.clone(),
            request_input: self.request_input.clone(),
            failed: Arc::clone(&self.failed),
        }
    }
}

impl<D: ResponseDocument> StoreSink<D> {
    fn new(store: Arc<dyn ResponseStore>, retention: Retention<D>) -> Self {
        Self {
            store,
            id: retention.id,
            request: retention.request,
            model: retention.model,
            created: retention.created,
            previous: retention.previous,
            request_input: retention.request_input,
            failed: retention.failed,
        }
    }

    /// Persist the terminal response unless it was cancelled while generating.
    async fn finish(&self, value: &D) -> Result<()> {
        if let Err(error) = self
            .put(
                value,
                WriteCondition::UnlessStatus(ResponseStatus::Cancelled),
            )
            .await
        {
            let persist_error = Error::new(
                ErrorCode::Backend,
                format!("failed to persist a completed response: {error}"),
            );
            if self.fail(&persist_error).await.is_err()
                && let Err(error) = self.store.delete(&self.id).await
            {
                tracing::warn!(target: "infer::agentic", %error, "unpersisted response could not be removed");
            }
            return Err(error);
        }
        // The conditional write is a no-op when another writer already recorded a terminal
        // state (cancel, or a disconnect cleanup). Report that so the caller does not publish a
        // completion for a response another writer terminated.
        if self.store.get(&self.id).await?.is_some_and(|stored| {
            matches!(
                stored.status,
                ResponseStatus::Cancelled | ResponseStatus::Failed
            )
        }) {
            return Err(Error::new(
                ErrorCode::Conflict,
                "response was terminated while completing",
            ));
        }
        Ok(())
    }

    /// Persist a failed response unless it was cancelled while generating.
    async fn fail(&self, error: &Error) -> Result<()> {
        let value = (self.failed)(error);
        match self
            .put(
                &value,
                WriteCondition::UnlessStatus(ResponseStatus::Cancelled),
            )
            .await
        {
            Ok(()) => Ok(()),
            Err(error) => {
                if let Err(error) = self.store.delete(&self.id).await {
                    tracing::warn!(target: "infer::agentic", %error, "unpersisted response could not be removed");
                }
                Err(error)
            }
        }
    }

    async fn put(&self, value: &D, condition: WriteCondition) -> Result<()> {
        let record = self.record(value)?;
        let limit = self.store.capabilities().max_record_bytes;
        let bytes = record
            .request_input
            .len()
            .checked_add(record.response.len())
            .ok_or_else(|| Error::invalid("stored response size overflow"))?;
        if bytes > limit {
            return Err(Error::new(
                ErrorCode::Capacity,
                "stored response exceeds the store record limit",
            ));
        }
        self.store.put(record, condition).await
    }

    fn record(&self, value: &D) -> Result<StoredResponse> {
        let metadata = value.metadata()?;
        let record = StoredResponse {
            id: self.id.clone(),
            request_id: self.request,
            model: self.model.clone(),
            created_at: self.created,
            completed_at: metadata.completed_at,
            status: metadata.status,
            incomplete: metadata.incomplete,
            error: metadata.error,
            usage: metadata.usage,
            previous_response_id: self.previous.clone(),
            request_input: self.request_input.clone(),
            response: value.encode()?,
            payload_version: RESPONSES_PAYLOAD_VERSION,
        };
        record.validate()?;
        Ok(record)
    }
}

/// Armed persistence guard for one response.
///
/// If the owner is dropped before a terminal write (a client disconnect drops the HTTP future
/// or SSE stream), the guard spawns a best-effort failure write, so the store never keeps an
/// active record forever merely because a client went away.
pub struct StoreLease<D: ResponseDocument> {
    sink: StoreSink<D>,
    armed: bool,
}

impl<D: ResponseDocument> StoreLease<D> {
    pub(crate) fn new(store: Arc<dyn ResponseStore>, retention: Retention<D>) -> Self {
        Self {
            sink: StoreSink::new(store, retention),
            armed: false,
        }
    }

    /// The engine request this lease retains.
    #[must_use]
    pub const fn request(&self) -> RequestId {
        self.sink.request
    }

    /// Write the initial snapshot and arm the disconnect cleanup.
    pub(crate) async fn start(&mut self, initial: &D) -> Result<()> {
        self.armed = true;
        let result = self.sink.put(initial, WriteCondition::Always).await;
        if result.is_err() {
            self.armed = false;
        }
        result
    }

    /// Write the terminal snapshot and disarm cleanup.
    ///
    /// # Errors
    /// Returns a capacity or backend error from the store, or a conflict when another writer
    /// (cancellation or disconnect cleanup) already terminated the response.
    pub async fn finish(&mut self, value: &D) -> Result<()> {
        let result = self.sink.finish(value).await;
        self.armed = false;
        result
    }

    /// Write a failed snapshot and disarm cleanup.
    ///
    /// # Errors
    /// Returns a capacity or backend error from the store.
    pub async fn fail(&mut self, error: &Error) -> Result<()> {
        let result = self.sink.fail(error).await;
        self.armed = false;
        result
    }
}

impl<D: ResponseDocument> Drop for StoreLease<D> {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        let sink = self.sink.clone();
        if let Ok(handle) = Handle::try_current() {
            handle.spawn(async move {
                let error = Error::new(
                    ErrorCode::Backend,
                    "response was abandoned before completion",
                );
                if let Err(store_error) = sink.fail(&error).await {
                    tracing::error!(
                        target: "infer::agentic",
                        error = %store_error,
                        "failed to retain an abandoned response"
                    );
                }
            });
        }
    }
}

//! Bounded in-process implementation of the Responses state extension.
//!
//! This is the reference backend installed by `--enable-response-store`. It is deliberately
//! process-local: it exists so a single-node deployment can use `store`, `previous_response_id`,
//! retrieval and background responses without an external service. An external SDK can install
//! its own [`infer_spi::ResponseStore`] through [`infer_spi::ResponsesExtensions`].
use infer_core::{Error, ErrorCode, Result};
use infer_spi::{
    RESPONSES_SPI_VERSION, ResponseEvent, ResponseFuture, ResponseId, ResponseStatus,
    ResponseStore, ResponseStoreCapabilities, StoredResponse, WriteCondition,
};
use std::collections::HashMap;
use std::future::ready;
use std::sync::{Mutex, MutexGuard};
use std::time::{Duration, Instant};

/// Default retained response count.
const DEFAULT_MAX_ENTRIES: usize = 256;
/// Default retained payload budget.
const DEFAULT_MAX_BYTES: usize = 64 * 1024 * 1024;
/// Default largest single record.
const DEFAULT_MAX_RECORD_BYTES: usize = 4 * 1024 * 1024;
/// Default retained background event count per response.
const DEFAULT_MAX_EVENTS: usize = 4096;
/// Default retention after the last access.
const DEFAULT_TTL: Duration = Duration::from_secs(60 * 60);

/// Tuning for [`InMemoryResponseStore`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InMemoryResponseStoreConfig {
    pub max_entries: usize,
    pub max_bytes: usize,
    pub max_record_bytes: usize,
    pub max_events: usize,
    /// `None` keeps terminal responses until eviction.
    pub ttl: Option<Duration>,
}

impl Default for InMemoryResponseStoreConfig {
    fn default() -> Self {
        Self {
            max_entries: DEFAULT_MAX_ENTRIES,
            max_bytes: DEFAULT_MAX_BYTES,
            max_record_bytes: DEFAULT_MAX_RECORD_BYTES,
            max_events: DEFAULT_MAX_EVENTS,
            ttl: Some(DEFAULT_TTL),
        }
    }
}

struct Entry {
    response: StoredResponse,
    last_used: u64,
    expires_at: Option<Instant>,
    bytes: usize,
}

struct Store {
    responses: HashMap<ResponseId, Entry>,
    events: HashMap<ResponseId, Vec<ResponseEvent>>,
    total_bytes: usize,
    clock: u64,
}

/// Process-local, bounded Responses store.
pub struct InMemoryResponseStore {
    config: InMemoryResponseStoreConfig,
    store: Mutex<Store>,
}

impl InMemoryResponseStore {
    /// Build a store with the supplied bounds.
    ///
    /// # Errors
    /// Returns an invalid-input error for zero limits or a per-record limit above the total
    /// budget.
    pub fn new(config: InMemoryResponseStoreConfig) -> Result<Self> {
        if config.max_entries == 0
            || config.max_bytes == 0
            || config.max_record_bytes == 0
            || config.max_events == 0
        {
            return Err(Error::invalid("response store limits must be nonzero"));
        }
        if config.max_record_bytes > config.max_bytes {
            return Err(Error::invalid(
                "response store per-record limit exceeds its total budget",
            ));
        }
        Ok(Self {
            config,
            store: Mutex::new(Store {
                responses: HashMap::new(),
                events: HashMap::new(),
                total_bytes: 0,
                clock: 0,
            }),
        })
    }

    /// The active tuning.
    #[must_use]
    pub const fn config(&self) -> InMemoryResponseStoreConfig {
        self.config
    }

    fn lock(&self) -> Result<MutexGuard<'_, Store>> {
        self.store
            .lock()
            .map_err(|_| Error::invariant("response store lock poisoned"))
    }

    const fn tick(store: &mut Store) -> u64 {
        store.clock = store.clock.wrapping_add(1);
        store.clock
    }

    fn purge_expired(&self, store: &mut Store) {
        if self.config.ttl.is_none() {
            return;
        }
        let now = Instant::now();
        let expired: Vec<ResponseId> = store
            .responses
            .iter()
            .filter(|(_, entry)| entry.response.status.is_terminal())
            .filter(|(_, entry)| entry.expires_at.is_some_and(|at| at <= now))
            .map(|(id, _)| id.clone())
            .collect();
        for id in expired {
            Self::remove(store, &id);
        }
    }

    fn remove(store: &mut Store, id: &ResponseId) {
        if let Some(entry) = store.responses.remove(id) {
            store.total_bytes = store.total_bytes.saturating_sub(entry.bytes);
        }
        store.events.remove(id);
    }

    fn eviction_candidates(
        store: &Store,
        keep: Option<&ResponseId>,
        needed_entries: usize,
        needed_bytes: usize,
    ) -> Result<Vec<ResponseId>> {
        let mut candidates: Vec<&ResponseId> = store
            .responses
            .iter()
            .filter(|(id, entry)| Some(*id) != keep && entry.response.status.is_terminal())
            .map(|(id, _)| id)
            .collect();
        candidates.sort_by_key(|id| store.responses.get(*id).map_or(0, |entry| entry.last_used));
        // `keep` is about to be replaced, so it is not part of the budget this write has to
        // free. Excluding it also avoids evicting an active response we are about to update.
        let mut entries = store.responses.len();
        let mut bytes = store.total_bytes;
        if let Some(entry) = keep.and_then(|id| store.responses.get(id)) {
            entries = entries.saturating_sub(1);
            bytes = bytes.saturating_sub(entry.bytes);
        }
        let mut selected = Vec::new();
        for id in candidates {
            if entries <= needed_entries && bytes <= needed_bytes {
                break;
            }
            let Some(entry) = store.responses.get(id) else {
                continue;
            };
            entries = entries.saturating_sub(1);
            bytes = bytes.saturating_sub(entry.bytes);
            selected.push(id.clone());
        }
        if entries > needed_entries || bytes > needed_bytes {
            return Err(Error::new(
                ErrorCode::Capacity,
                "response store retention budget is exhausted by active responses",
            ));
        }
        Ok(selected)
    }

    fn get_sync(&self, id: &ResponseId) -> Result<Option<StoredResponse>> {
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        let clock = Self::tick(&mut store);
        let Some(entry) = store.responses.get_mut(id) else {
            return Ok(None);
        };
        entry.last_used = clock;
        let response = entry.response.clone();
        drop(store);
        Ok(Some(response))
    }

    fn put_sync(&self, response: StoredResponse, condition: WriteCondition) -> Result<()> {
        response.validate()?;
        let bytes = response
            .request_input
            .len()
            .checked_add(response.response.len())
            .ok_or_else(|| Error::invalid("stored response size overflow"))?;
        if bytes > self.config.max_record_bytes {
            return Err(Error::new(
                ErrorCode::Capacity,
                "stored response exceeds the per-record byte limit",
            ));
        }
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        if let Some(entry) = store.responses.get(&response.id)
            && match condition {
                WriteCondition::Always => false,
                WriteCondition::UnlessStatus(status) => entry.response.status == status,
                WriteCondition::UnlessTerminal => entry.response.status.is_terminal(),
            }
        {
            return Ok(());
        }
        let replacing = store
            .responses
            .get(&response.id)
            .map_or(0, |entry| entry.bytes);
        let existing = usize::from(store.responses.contains_key(&response.id));
        let needed_entries = self.config.max_entries.saturating_sub(1);
        let needed_bytes = self.config.max_bytes.saturating_sub(bytes);
        let base_entries = store.responses.len().saturating_sub(existing);
        let base_bytes = store.total_bytes.saturating_sub(replacing);
        let candidates = if base_entries.saturating_add(1) > self.config.max_entries
            || base_bytes > needed_bytes
        {
            Self::eviction_candidates(&store, Some(&response.id), needed_entries, needed_bytes)?
        } else {
            Vec::new()
        };
        for id in candidates {
            Self::remove(&mut store, &id);
        }
        Self::remove(&mut store, &response.id);
        let expires_at = self
            .config
            .ttl
            .and_then(|ttl| Instant::now().checked_add(ttl));
        let clock = Self::tick(&mut store);
        store.responses.insert(
            response.id.clone(),
            Entry {
                response,
                last_used: clock,
                expires_at,
                bytes,
            },
        );
        store.total_bytes = store.total_bytes.checked_add(bytes).ok_or_else(|| {
            Error::new(
                ErrorCode::Capacity,
                "response store byte accounting overflow",
            )
        })?;
        drop(store);
        Ok(())
    }

    fn delete_sync(&self, id: &ResponseId) -> Result<()> {
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        Self::remove(&mut store, id);
        Ok(())
    }

    fn transition_sync(
        &self,
        id: &ResponseId,
        allowed: &[ResponseStatus],
        next: ResponseStatus,
    ) -> Result<StoredResponse> {
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        let clock = Self::tick(&mut store);
        let entry = store
            .responses
            .get_mut(id)
            .ok_or_else(|| Error::new(ErrorCode::NotFound, "stored response not found"))?;
        let current = entry.response.status;
        if !allowed.contains(&current) || !current.can_transition_to(next) {
            return Err(Error::new(
                ErrorCode::Conflict,
                format!("response status {current} cannot transition to {next}"),
            ));
        }
        entry.response.status = next;
        entry.last_used = clock;
        entry.expires_at = self
            .config
            .ttl
            .and_then(|ttl| Instant::now().checked_add(ttl));
        let response = entry.response.clone();
        drop(store);
        Ok(response)
    }

    fn append_event_sync(&self, id: &ResponseId, event: ResponseEvent) -> Result<()> {
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        if !store.responses.contains_key(id) {
            return Err(Error::new(ErrorCode::NotFound, "stored response not found"));
        }
        let events = store.events.entry(id.clone()).or_default();
        if events
            .last()
            .is_some_and(|last| last.sequence >= event.sequence)
        {
            return Err(Error::invalid(
                "response events must have increasing sequence numbers",
            ));
        }
        if events.len() >= self.config.max_events {
            return Err(Error::new(
                ErrorCode::Capacity,
                "response event retention is full",
            ));
        }
        events.push(event);
        drop(store);
        Ok(())
    }

    fn events_sync(&self, id: &ResponseId, after: Option<u64>) -> Result<Vec<ResponseEvent>> {
        let mut store = self.lock()?;
        self.purge_expired(&mut store);
        let Some(events) = store.events.get(id) else {
            return Ok(Vec::new());
        };
        let events = events
            .iter()
            .filter(|event| after.is_none_or(|after| event.sequence > after))
            .cloned()
            .collect();
        drop(store);
        Ok(events)
    }
}

impl Default for InMemoryResponseStore {
    fn default() -> Self {
        Self {
            config: InMemoryResponseStoreConfig::default(),
            store: Mutex::new(Store {
                responses: HashMap::new(),
                events: HashMap::new(),
                total_bytes: 0,
                clock: 0,
            }),
        }
    }
}

impl ResponseStore for InMemoryResponseStore {
    fn capabilities(&self) -> ResponseStoreCapabilities {
        ResponseStoreCapabilities {
            retrieve: true,
            previous_response_id: true,
            background: true,
            cancel: true,
            event_replay: true,
            persistent: false,
            shared: false,
            max_record_bytes: self.config.max_record_bytes,
        }
    }

    fn spi_version(&self) -> u32 {
        RESPONSES_SPI_VERSION
    }

    fn get<'a>(&'a self, id: &'a ResponseId) -> ResponseFuture<'a, Option<StoredResponse>> {
        Box::pin(ready(self.get_sync(id)))
    }

    fn put(&self, response: StoredResponse, condition: WriteCondition) -> ResponseFuture<'_, ()> {
        Box::pin(ready(self.put_sync(response, condition)))
    }

    fn delete<'a>(&'a self, id: &'a ResponseId) -> ResponseFuture<'a, ()> {
        Box::pin(ready(self.delete_sync(id)))
    }

    fn transition<'a>(
        &'a self,
        id: &'a ResponseId,
        allowed: &'a [ResponseStatus],
        next: ResponseStatus,
    ) -> ResponseFuture<'a, StoredResponse> {
        Box::pin(ready(self.transition_sync(id, allowed, next)))
    }

    fn append_event<'a>(
        &'a self,
        id: &'a ResponseId,
        event: ResponseEvent,
    ) -> ResponseFuture<'a, ()> {
        Box::pin(ready(self.append_event_sync(id, event)))
    }

    fn events<'a>(
        &'a self,
        id: &'a ResponseId,
        after: Option<u64>,
    ) -> ResponseFuture<'a, Vec<ResponseEvent>> {
        Box::pin(ready(self.events_sync(id, after)))
    }
}

