//! Typed server-sent events for the `OpenAI` Responses protocol.
//!
//! Both the streamed and the complete reply come from the same admission path, so they accept the
//! same requests and resolve the same limits. Each committed token is detokenized and parsed once
//! on the delivery pool, and a published delta is never rewritten.
use super::super::TextState;
use super::super::execution::{Prepared as GenerationPrepared, finish_reason};
use super::events::ResponseEvent;
use super::output::{
    self, IncompleteDetails, ResponseBody, ResponseErrorBody, ResponseItem, Snapshot, Usage,
};
use super::request::Spec;
use crate::cpu::CpuPool;
use axum::response::sse::{Event, KeepAlive, Sse};
use axum::response::{IntoResponse, Response};
use futures_util::stream::unfold;
use infer_agentic::StoreLease;
use infer_core::{Error, ErrorCode, RequestId};
use infer_models::{OutputStreamParser, StreamEvent, TextStreamDecoder};
use infer_runtime::EngineOutput;

use std::collections::VecDeque;
use std::convert::Infallible;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::sync::mpsc;

/// Lifecycle of one event stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Phase {
    Running,
    /// The terminal response event has been queued.
    Done,
}

/// An assistant message whose content is still streaming.
struct OpenMessage {
    index: usize,
    item_id: String,
    text: String,
}

/// A reasoning item whose text is still streaming.
struct OpenReasoning {
    index: usize,
    item_id: String,
    text: String,
}

/// A function call whose arguments are still streaming.
struct OpenCall {
    index: usize,
    call_index: usize,
    item_id: String,
    name: String,
    arguments: String,
}

/// One streamed generation in progress.
struct Stream {
    request: RequestId,
    receiver: mpsc::Receiver<infer_core::Result<EngineOutput>>,
    delivery: CpuPool,
    /// The decoder and parser leave this owner for the duration of a CPU job and come back.
    decoder: Option<TextStreamDecoder>,
    parser: Option<OutputStreamParser>,
    /// Set by prompt encoding before the first engine event; consumed once.
    prompt_reasoning: Option<Arc<AtomicBool>>,
    /// SSE event name and serialized payload waiting to be written.
    queue: VecDeque<(String, String)>,
    sequence: u64,
    model: String,
    created: u64,
    spec: Spec,
    temperature: f32,
    top_p: f32,
    prompt_tokens: Arc<AtomicUsize>,
    completion_tokens: usize,
    /// Completed output items, in output order.
    output: Vec<ResponseItem>,
    message: Option<OpenMessage>,
    reasoning: Option<OpenReasoning>,
    call: Option<OpenCall>,
    /// Terminal response persistence, when the request asked to store its result.
    lease: Option<StoreLease<ResponseBody>>,
    /// Output index the next item receives.
    next_index: usize,
    /// Calls published so far, which is also their `call_id` ordinal.
    calls: usize,
    phase: Phase,
}

fn encode<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_string(value).unwrap_or_default()
}

impl Stream {
    /// Serialize one event with the next sequence number.
    fn emit(&mut self, build: impl FnOnce(u64) -> ResponseEvent) {
        let sequence_number = self.sequence;
        self.sequence += 1;
        let event = build(sequence_number);
        let name = event.kind();
        self.queue.push_back((name.to_string(), encode(&event)));
    }

    /// The response object at this point in the lifecycle.
    fn response(
        &self,
        status: &str,
        completed_at: Option<u64>,
        incomplete: Option<IncompleteDetails>,
        error: Option<ResponseErrorBody>,
        usage: Option<&Usage>,
    ) -> ResponseBody {
        Snapshot {
            request: self.request,
            created: self.created,
            completed_at,
            model: &self.model,
            status,
            incomplete,
            error,
            output: &self.output,
            spec: &self.spec,
            temperature: self.temperature,
            top_p: self.top_p,
            usage,
        }
        .value()
    }

    /// Publish `response.created` and `response.in_progress` before the first token.
    fn start(&mut self) {
        let response = self.response("in_progress", None, None, None, None);
        self.emit(|sequence_number| ResponseEvent::Created {
            response: response.clone(),
            sequence_number,
        });
        self.emit(|sequence_number| ResponseEvent::InProgress {
            response,
            sequence_number,
        });
    }

    fn item_namespace(&self) -> String {
        self.spec
            .response_id
            .clone()
            .unwrap_or_else(|| self.request.to_string())
    }

    /// Open a reasoning item and publish its arrival.
    fn open_reasoning(&mut self) {
        let index = self.next_index;
        self.next_index += 1;
        let namespace = self.item_namespace();
        let item_id = format!("rs_{namespace}_{index}");
        let item = output::reasoning_item(&namespace, index, "", "in_progress");
        self.emit(|sequence_number| ResponseEvent::OutputItemAdded {
            output_index: index,
            item,
            sequence_number,
        });
        self.reasoning = Some(OpenReasoning {
            index,
            item_id,
            text: String::new(),
        });
    }

    /// Open an assistant message and its first content part.
    fn open_message(&mut self) {
        let index = self.next_index;
        self.next_index += 1;
        let namespace = self.item_namespace();
        let item_id = format!("msg_{namespace}_{index}");
        let item = output::message_item(&namespace, index, "", "in_progress");
        self.emit(|sequence_number| ResponseEvent::OutputItemAdded {
            output_index: index,
            item,
            sequence_number,
        });
        self.emit(|sequence_number| ResponseEvent::ContentPartAdded {
            item_id: item_id.clone(),
            output_index: index,
            content_index: 0,
            part: output::output_text_part(""),
            sequence_number,
        });
        self.message = Some(OpenMessage {
            index,
            item_id,
            text: String::new(),
        });
    }

    /// Open a function call item with empty arguments.
    fn open_call(&mut self, name: &str) {
        let index = self.next_index;
        self.next_index += 1;
        let call_index = self.calls;
        self.calls += 1;
        let namespace = self.item_namespace();
        let item_id = output::call_item_id(&namespace, call_index);
        let item = output::function_call_item(&namespace, call_index, name, "", "in_progress");
        self.emit(|sequence_number| ResponseEvent::OutputItemAdded {
            output_index: index,
            item,
            sequence_number,
        });
        self.call = Some(OpenCall {
            index,
            call_index,
            item_id,
            name: name.to_string(),
            arguments: String::new(),
        });
    }

    /// Finish and publish the open reasoning item.
    fn close_reasoning(&mut self, status: &'static str) {
        let Some(open) = self.reasoning.take() else {
            return;
        };
        self.emit(|sequence_number| ResponseEvent::ReasoningTextDone {
            item_id: open.item_id.clone(),
            output_index: open.index,
            content_index: 0,
            text: open.text.clone(),
            sequence_number,
        });
        let namespace = self.item_namespace();
        let item = output::reasoning_item(&namespace, open.index, &open.text, status);
        self.emit(|sequence_number| ResponseEvent::OutputItemDone {
            output_index: open.index,
            item: item.clone(),
            sequence_number,
        });
        self.output.push(item);
    }

    /// Finish and publish the open assistant message.
    fn close_message(&mut self, status: &'static str) {
        let Some(open) = self.message.take() else {
            return;
        };
        let part = output::output_text_part(&open.text);
        self.emit(|sequence_number| ResponseEvent::OutputTextDone {
            item_id: open.item_id.clone(),
            output_index: open.index,
            content_index: 0,
            text: open.text.clone(),
            logprobs: Vec::new(),
            sequence_number,
        });
        self.emit(|sequence_number| ResponseEvent::ContentPartDone {
            item_id: open.item_id.clone(),
            output_index: open.index,
            content_index: 0,
            part,
            sequence_number,
        });
        let namespace = self.item_namespace();
        let item = output::message_item(&namespace, open.index, &open.text, status);
        self.emit(|sequence_number| ResponseEvent::OutputItemDone {
            output_index: open.index,
            item: item.clone(),
            sequence_number,
        });
        self.output.push(item);
    }

    /// Finish and publish the open function call.
    fn close_call(&mut self, status: &'static str) {
        let Some(open) = self.call.take() else {
            return;
        };
        self.emit(|sequence_number| ResponseEvent::FunctionCallArgumentsDone {
            item_id: open.item_id.clone(),
            output_index: open.index,
            arguments: open.arguments.clone(),
            sequence_number,
        });
        let namespace = self.item_namespace();
        let item = output::function_call_item(
            &namespace,
            open.call_index,
            &open.name,
            &open.arguments,
            status,
        );
        self.emit(|sequence_number| ResponseEvent::OutputItemDone {
            output_index: open.index,
            item: item.clone(),
            sequence_number,
        });
        self.output.push(item);
    }

    /// Finish every open item; a normal finish completes them and an interruption does not.
    fn close_open(&mut self, status: &'static str) {
        self.close_call(status);
        self.close_message(status);
        self.close_reasoning(status);
    }

    /// Publish one parser event.
    fn publish(&mut self, event: StreamEvent) {
        match event {
            StreamEvent::Reasoning(text) => self.publish_reasoning(&text),
            StreamEvent::Text(text) => self.publish_text(&text),
            StreamEvent::CallStart { name, .. } => self.publish_call_start(&name),
            StreamEvent::CallArguments { arguments, .. } => self.publish_arguments(&arguments),
            StreamEvent::CallEnd { .. } => self.close_call("completed"),
            StreamEvent::Call(call) => self.publish_complete_call(&call.name, &call.arguments),
        }
    }

    fn publish_reasoning(&mut self, text: &str) {
        if self.message.is_some() {
            self.close_message("completed");
        }
        if self.call.is_some() {
            self.close_call("completed");
        }
        if self.reasoning.is_none() {
            self.open_reasoning();
        }
        let delta = self.reasoning.as_mut().map(|open| {
            open.text.push_str(text);
            (open.item_id.clone(), open.index)
        });
        if let Some((item_id, index)) = delta {
            self.emit(|sequence_number| ResponseEvent::ReasoningTextDelta {
                item_id,
                output_index: index,
                content_index: 0,
                delta: text.to_string(),
                sequence_number,
            });
        }
    }

    fn publish_text(&mut self, text: &str) {
        if self.reasoning.is_some() {
            self.close_reasoning("completed");
        }
        if self.call.is_some() {
            self.close_call("completed");
        }
        if self.message.is_none() {
            self.open_message();
        }
        let delta = self.message.as_mut().map(|open| {
            open.text.push_str(text);
            (open.item_id.clone(), open.index)
        });
        if let Some((item_id, index)) = delta {
            self.emit(|sequence_number| ResponseEvent::OutputTextDelta {
                item_id,
                output_index: index,
                content_index: 0,
                delta: text.to_string(),
                logprobs: Vec::new(),
                sequence_number,
            });
        }
    }

    fn publish_call_start(&mut self, name: &str) {
        self.close_reasoning("completed");
        self.close_message("completed");
        if self.call.is_some() {
            self.close_call("completed");
        }
        self.open_call(name);
    }

    fn publish_arguments(&mut self, arguments: &str) {
        let delta = self.call.as_mut().map(|open| {
            open.arguments.push_str(arguments);
            (open.item_id.clone(), open.index)
        });
        if let Some((item_id, index)) = delta {
            self.emit(
                |sequence_number| ResponseEvent::FunctionCallArgumentsDelta {
                    item_id,
                    output_index: index,
                    delta: arguments.to_string(),
                    sequence_number,
                },
            );
        }
    }

    /// Publish a complete call reported as one event, for dialects that withhold a block.
    fn publish_complete_call(&mut self, name: &str, arguments: &str) {
        self.publish_call_start(name);
        self.publish_arguments(arguments);
        self.close_call("completed");
    }

    /// Publish everything produced by one engine event.
    ///
    /// # Errors
    /// Returns a decoding or parsing error for a response that cannot be published incrementally.
    async fn advance(&mut self, event: EngineOutput) -> infer_core::Result<()> {
        if let Some(open) = self.prompt_reasoning.take() {
            let parser = self
                .parser
                .take()
                .ok_or_else(|| Error::invariant("stream parser missing"))?;
            self.parser = Some(parser.with_open_reasoning(open.load(Ordering::Acquire)));
        }
        match event {
            EngineOutput::Token { token, .. } => self.advance_token(token).await,
            EngineOutput::Finished(result) => self.finish(result).await,
        }
    }

    async fn advance_token(&mut self, token: u32) -> infer_core::Result<()> {
        self.completion_tokens += 1;
        let delivery = self.delivery.clone();
        let decoder = self
            .decoder
            .take()
            .ok_or_else(|| Error::invariant("stream decoder missing"))?;
        let parser = self
            .parser
            .take()
            .ok_or_else(|| Error::invariant("stream parser missing"))?;
        let (decoder, parser, events) = delivery
            .run(0, move |_| {
                let mut decoder = decoder;
                let mut parser = parser;
                let text = decoder.push(token)?;
                let events = if text.is_empty() {
                    Vec::new()
                } else {
                    parser.feed(&text)?
                };
                Ok((decoder, parser, events))
            })
            .await?;
        self.decoder = Some(decoder);
        self.parser = Some(parser);
        for event in events {
            self.publish(event);
        }
        Ok(())
    }

    async fn finish(&mut self, result: infer_runtime::CompletedRequest) -> infer_core::Result<()> {
        let delivery = self.delivery.clone();
        let decoder = self
            .decoder
            .take()
            .ok_or_else(|| Error::invariant("stream decoder missing"))?;
        let parser = self
            .parser
            .take()
            .ok_or_else(|| Error::invariant("stream parser missing"))?;
        let (decoder, parser, events) = delivery
            .run(0, move |_| {
                let mut decoder = decoder;
                let mut parser = parser;
                let tail = decoder.finish()?;
                let mut events = if tail.is_empty() {
                    Vec::new()
                } else {
                    parser.feed(&tail)?
                };
                events.extend(parser.finish()?);
                Ok((decoder, parser, events))
            })
            .await?;
        self.decoder = Some(decoder);
        self.parser = Some(parser);
        for event in events {
            self.publish(event);
        }
        let reason = finish_reason(&result.reason)?;
        let truncated = self
            .parser
            .as_ref()
            .is_some_and(OutputStreamParser::truncated);
        if truncated && reason != "length" {
            return Err(Error::new(
                ErrorCode::Backend,
                "model output ended inside a structured region",
            ));
        }
        let (status, item_status) = if reason == "length" {
            ("incomplete", "incomplete")
        } else {
            ("completed", "completed")
        };
        self.close_open(item_status);
        // A response with no message or call still carries the assistant message item the
        // complete route produces, so both routes expose the same output shape.
        let has_turn = self.output.iter().any(|item| {
            matches!(
                item,
                ResponseItem::Message(_) | ResponseItem::FunctionCall(_)
            )
        });
        if !has_turn {
            self.open_message();
            self.close_message(item_status);
        }
        let usage = Usage {
            input: self.prompt_tokens.load(Ordering::Relaxed),
            output: self.completion_tokens,
            reasoning: 0,
        };
        let incomplete = (reason == "length").then_some(IncompleteDetails {
            reason: "max_output_tokens".to_string(),
        });
        let completed_at = (reason != "length").then(now).transpose()?;
        let response = self.response(status, completed_at, incomplete, None, Some(&usage));
        if let Some(lease) = &mut self.lease {
            lease.finish(&response).await?;
        }
        if reason == "length" {
            self.emit(|sequence_number| ResponseEvent::Incomplete {
                response,
                sequence_number,
            });
        } else {
            self.emit(|sequence_number| ResponseEvent::Completed {
                response,
                sequence_number,
            });
        }
        self.phase = Phase::Done;
        Ok(())
    }

    /// Publish a terminal failure event and end the stream.
    async fn fail(&mut self, error: &Error) {
        if let Some(lease) = &mut self.lease
            && let Err(store_error) = lease.fail(error).await
        {
            tracing::error!(
                target: "infer::openai",
                error = %store_error,
                "failed to retain a failed response"
            );
        }
        self.close_open("incomplete");
        let code = error_code(error.code);
        let response = self.response(
            "failed",
            None,
            None,
            Some(ResponseErrorBody {
                code: code.to_string(),
                message: error.message.clone(),
            }),
            None,
        );
        self.emit(|sequence_number| ResponseEvent::Error {
            code,
            message: error.message.clone(),
            param: None,
            sequence_number,
        });
        self.emit(|sequence_number| ResponseEvent::Failed {
            response,
            sequence_number,
        });
        self.phase = Phase::Done;
    }
}

const fn error_code(code: ErrorCode) -> &'static str {
    match code {
        ErrorCode::InvalidInput => "invalid_request",
        ErrorCode::Unsupported => "unsupported_feature",
        ErrorCode::NotFound => "model_not_found",
        ErrorCode::Conflict => "request_conflict",
        ErrorCode::Capacity => "capacity_exceeded",
        ErrorCode::Backend => "backend_error",
        ErrorCode::Invariant => "internal_error",
    }
}

fn now() -> infer_core::Result<u64> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .map_err(|error| Error::new(ErrorCode::Backend, error.to_string()))
}

/// Stream one admitted Responses generation as typed server-sent events.
pub(super) fn stream(
    state: &TextState,
    prepared: GenerationPrepared,
    spec: Spec,
    lease: Option<StoreLease<ResponseBody>>,
) -> Response {
    let mut stream = Stream {
        request: prepared.request,
        receiver: prepared.receiver,
        delivery: state.delivery.clone(),
        decoder: Some(state.assets.stream_decoder()),
        parser: Some(
            OutputStreamParser::new(prepared.dialect, prepared.policy.declared().cloned())
                .with_tools(prepared.policy.parses())
                .with_argument_deltas(),
        ),
        prompt_reasoning: Some(prepared.reasoning_open),
        queue: VecDeque::new(),
        sequence: 0,
        model: prepared.model_name.clone(),
        created: prepared.created,
        spec,
        temperature: prepared.temperature,
        top_p: prepared.top_p,
        prompt_tokens: prepared.prompt_tokens,
        completion_tokens: 0,
        output: Vec::new(),
        message: None,
        reasoning: None,
        call: None,
        lease,
        next_index: 0,
        calls: 0,
        phase: Phase::Running,
    };
    stream.start();
    let events = unfold(stream, |mut stream| async move {
        loop {
            if let Some((name, data)) = stream.queue.pop_front() {
                return Some((
                    Ok::<_, Infallible>(Event::default().event(name).data(data)),
                    stream,
                ));
            }
            if stream.phase == Phase::Done {
                return None;
            }
            match stream.receiver.recv().await {
                None => {
                    let error = Error::new(
                        ErrorCode::Backend,
                        "request stream closed before completion",
                    );
                    stream.fail(&error).await;
                }
                Some(Err(error)) => stream.fail(&error).await,
                Some(Ok(event)) => {
                    if let Err(error) = stream.advance(event).await {
                        stream.fail(&error).await;
                    }
                }
            }
        }
    });
    Sse::new(events)
        .keep_alive(KeepAlive::default())
        .into_response()
}

//! Wire-side persistence glue: the Responses body as an [`infer_agentic::ResponseDocument`].
//!
//! Lifecycles, conditional writes and the disconnect guard live in `infer-agentic`; this module
//! only maps the typed `OpenAI` response object to store metadata and back.
use super::super::execution::Prepared as GenerationPrepared;
use super::super::request::OpaqueJson;
use super::output;
use super::output::{
    IncompleteDetails, ResponseBody, ResponseErrorBody, ResponseUsageBody, Snapshot,
};
use super::request::{PriorState, Spec};
use infer_agentic::{DocumentMetadata, ResponseDocument, Retention};
use infer_core::{Error, ErrorCode, RequestId, Result};
use infer_spi::{
    IncompleteReason, ResponseError, ResponseId, ResponseStatus, ResponseUsage, StoredResponse,
};
use std::sync::Arc;

impl ResponseDocument for ResponseBody {
    fn metadata(&self) -> Result<DocumentMetadata> {
        Ok(DocumentMetadata {
            status: self.status.parse::<ResponseStatus>()?,
            completed_at: self.completed_at,
            incomplete: self
                .incomplete_details
                .as_ref()
                .map(|details| incomplete_reason(&details.reason))
                .transpose()?,
            error: self
                .error
                .as_ref()
                .map(|error| ResponseError::new(&error.code, &error.message))
                .transpose()?,
            usage: self.usage.as_ref().map(response_usage),
        })
    }

    fn encode(&self) -> Result<Vec<u8>> {
        serde_json::to_vec(self)
            .map_err(|error| Error::invalid(format!("response serialization: {error}")))
    }
}

/// The parts of one admitted response that every lifecycle snapshot repeats.
#[derive(Clone)]
struct Envelope {
    request: RequestId,
    created: u64,
    model: String,
    temperature: f32,
    top_p: f32,
    spec: Spec,
}

impl Envelope {
    fn new(prepared: &GenerationPrepared, spec: &Spec) -> Self {
        Self {
            request: prepared.request,
            created: prepared.created,
            model: prepared.model_name.clone(),
            temperature: prepared.temperature,
            top_p: prepared.top_p,
            spec: spec.clone(),
        }
    }

    fn body(&self, status: &str, error: Option<ResponseErrorBody>) -> ResponseBody {
        Snapshot {
            request: self.request,
            created: self.created,
            completed_at: None,
            model: &self.model,
            status,
            incomplete: None,
            error,
            output: &[],
            spec: &self.spec,
            temperature: self.temperature,
            top_p: self.top_p,
            usage: None,
        }
        .value()
    }

    fn failed(&self, error: &Error) -> ResponseBody {
        self.body(
            "failed",
            Some(ResponseErrorBody {
                code: error_code(error.code).to_string(),
                message: error.message.clone(),
            }),
        )
    }
}

/// The in-progress snapshot written when an admitted response is first retained.
pub(super) fn initial(prepared: &GenerationPrepared, spec: &Spec) -> ResponseBody {
    Envelope::new(prepared, spec).body("in_progress", None)
}

/// Bind one admitted generation to its store identity.
///
/// # Errors
/// Returns an invalid-input error when the generated identity or a chained identifier cannot
/// be represented in the store contract.
pub(super) fn retention(
    prepared: &GenerationPrepared,
    spec: &Spec,
    request_input: Vec<u8>,
) -> Result<Retention<ResponseBody>> {
    let id = match spec.response_id.as_deref() {
        Some(id) => ResponseId::new(id)?,
        None => ResponseId::new(format!("resp_{}", prepared.request.get()))?,
    };
    let previous = spec
        .previous_response_id
        .as_deref()
        .map(ResponseId::new)
        .transpose()?;
    let envelope = Envelope::new(prepared, spec);
    Ok(Retention {
        id,
        request: prepared.request,
        model: prepared.model_name.clone(),
        created: prepared.created,
        previous,
        request_input,
        failed: Arc::new(move |error| envelope.failed(error)),
    })
}

/// Reconstruct the prior conversation of a validated `previous_response_id` record.
///
/// # Errors
/// Returns an invariant error when the stored payloads do not decode.
pub(super) fn prior_state(stored: &StoredResponse) -> Result<PriorState> {
    let input: Vec<OpaqueJson> = serde_json::from_slice(&stored.request_input)
        .map_err(|error| Error::invariant(format!("stored input payload is invalid: {error}")))?;
    let response: ResponseBody = serde_json::from_slice(&stored.response).map_err(|error| {
        Error::invariant(format!("stored response payload is invalid: {error}"))
    })?;
    let output = response
        .output()
        .iter()
        .map(|item| {
            serde_json::to_value(item)
                .map(OpaqueJson)
                .map_err(|error| Error::invariant(format!("stored output is invalid: {error}")))
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(PriorState {
        input,
        output,
        model: stored.model.clone(),
    })
}

/// Decode a stored response and overlay the metadata that may be newer than the body.
///
/// A cancel transition intentionally does not rewrite the opaque body; the overlay keeps the
/// returned status, error, incomplete reason and usage authoritative.
///
/// # Errors
/// Returns an invariant error if the stored body is not a JSON object.
pub(super) fn retrieved(stored: &StoredResponse) -> Result<ResponseBody> {
    let mut value: ResponseBody = serde_json::from_slice(&stored.response).map_err(|error| {
        Error::invariant(format!("stored response payload is invalid: {error}"))
    })?;
    value.status = stored.status.as_str().to_string();
    value.completed_at = stored.completed_at;
    value.error = stored.error.as_ref().map(|error| ResponseErrorBody {
        code: error.code.clone(),
        message: error.message.clone(),
    });
    value.incomplete_details = stored.incomplete.map(|reason| IncompleteDetails {
        reason: reason.as_str().to_string(),
    });
    value.usage = stored.usage.map(response_usage_body);
    Ok(value)
}

fn incomplete_reason(reason: &str) -> Result<IncompleteReason> {
    Ok(match reason {
        "max_output_tokens" => IncompleteReason::MaxOutputTokens,
        "max_messages" => IncompleteReason::MaxMessages,
        "content_filter" => IncompleteReason::ContentFilter,
        other => {
            return Err(Error::invariant(format!(
                "unknown incomplete reason {other:?}"
            )));
        }
    })
}

fn response_usage(usage: &ResponseUsageBody) -> ResponseUsage {
    ResponseUsage {
        input_tokens: u64::try_from(usage.input_tokens).unwrap_or(u64::MAX),
        output_tokens: u64::try_from(usage.output_tokens).unwrap_or(u64::MAX),
        reasoning_tokens: u64::try_from(usage.output_tokens_details.reasoning_tokens)
            .unwrap_or(u64::MAX),
        cached_tokens: u64::try_from(usage.input_tokens_details.cached_tokens).unwrap_or(u64::MAX),
        cache_write_tokens: u64::try_from(usage.input_tokens_details.cache_write_tokens)
            .unwrap_or(u64::MAX),
    }
}

fn response_usage_body(usage: ResponseUsage) -> ResponseUsageBody {
    ResponseUsageBody {
        input_tokens: usize::try_from(usage.input_tokens).unwrap_or(usize::MAX),
        input_tokens_details: output::InputTokensDetails {
            cached_tokens: usize::try_from(usage.cached_tokens).unwrap_or(usize::MAX),
            cache_write_tokens: usize::try_from(usage.cache_write_tokens).unwrap_or(usize::MAX),
        },
        output_tokens: usize::try_from(usage.output_tokens).unwrap_or(usize::MAX),
        output_tokens_details: output::OutputTokensDetails {
            reasoning_tokens: usize::try_from(usage.reasoning_tokens).unwrap_or(usize::MAX),
        },
        total_tokens: usage
            .checked_total()
            .and_then(|total| usize::try_from(total).ok())
            .unwrap_or(usize::MAX),
    }
}

/// Storage-safe spelling of an error code for a failed response object.
pub(super) const fn error_code(code: ErrorCode) -> &'static str {
    match code {
        ErrorCode::InvalidInput => "invalid_request",
        ErrorCode::Unsupported => "unsupported_feature",
        ErrorCode::NotFound => "response_not_found",
        ErrorCode::Conflict => "request_conflict",
        ErrorCode::Capacity => "capacity_exceeded",
        ErrorCode::Backend => "backend_error",
        ErrorCode::Invariant => "internal_error",
    }
}
